import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    result = {}
    network = IPv4Network(ip_range)
    for ip in network:
        ip_str = str(ip)
        try:
            subprocess.run(['ping', '-c', '1', '-W', '1', ip_str], capture_output=True, check=True)
            result[ip_str] = True
        except subprocess.CalledProcessError:
            result[ip_str] = False
    return result
